require_once __DIR__.'/../includes/auth.php';require_once __DIR__.'/../includes/schema.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Méthode non autorisée.');}require_admin();csrf_check();$schema=dental_schema($pdo);$labIdColumn=$schema->labId();$id=(int)($_POST['laboratoire_id']??0);$status=(string)($_POST['statut']??'');if($id<1||!in_array($status,['en_attente','valide','rejete'],true)){http_response_code(400);exit('Statut invalide.');}$q=$pdo->prepare("UPDATE laboratoire SET statut=? WHERE `$labIdColumn`=?");$q->execute([$schema->status($status),$id]);if($q->rowCount()!==1){$_SESSION['admin_flash']=['type'=>'error','message'=>'Le statut n’a pas été modifié. Le dossier a peut-être déjà été traité.'];}else{$_SESSION['admin_flash']=['type'=>'success','message'=>'Laboratoire '.['en_attente'=>'remis en attente','valide'=>'validé','rejete'=>'rejeté'][$status].'.'];}header('Location: ../admin/validation.php');exit;
